import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, mix, mul, sub, add, sin, fract, dot, Fn, color, smoothstep, length, sub as tslSub } from 'three/tsl';
import { gsap } from 'gsap';

const COLORS = {
  ink: '#16161d',
  paper: '#e8ecf2',
  accent: '#ff2a38',
  surface: '#0b0b10',
};

// simple hash-based static grain node
const grainNode = Fn(([inputUv]) => {
  const n = fract(sin(dot(inputUv, vec2(12.9898, 78.233))).mul(43758.5453));
  return n;
});

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, PlaneGeometry, BoxGeometry, PointLight, DoubleSide, Color, SRGBColorSpace } = THREE;

  const group = new Group();
  group.name = 'journal-card-1';

  const width = 1.9;
  const height = width / (512 / 320); // matches atlas aspect ratio ~1.6

  // ---- Backdrop card (engineered gradient surface, PBR, subtle grain) ----
  const cardDepth = 0.05;
  const cardGeo = new BoxGeometry(width, height, cardDepth);
  const cardMat = new MeshStandardNodeMaterial({
    roughness: 0.6,
    metalness: 0.3,
    side: DoubleSide,
  });

  const gradientBase = mix(color(COLORS.ink), color(COLORS.surface), uv().y);
  const grain = grainNode(uv()).sub(0.5).mul(0.035);
  cardMat.colorNode = gradientBase.add(grain);

  const cardMesh = new THREE.Mesh(cardGeo, cardMat);
  cardMesh.position.z = -0.03;
  group.add(cardMesh);

  // ---- micro drop-shadow (depth separation, radial falloff) ----
  const shadowGeo = new PlaneGeometry(width * 1.25, height * 1.25);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, side: DoubleSide });
  const suv = uv().sub(vec2(0.5, 0.5)).mul(2.0);
  const dist = length(suv);
  const falloff = smoothstep(1.0, 0.2, dist);
  shadowMat.colorNode = color('#000000');
  shadowMat.opacityNode = falloff.mul(0.45);
  const shadowMesh = new THREE.Mesh(shadowGeo, shadowMat);
  shadowMesh.position.z = -0.09;
  group.add(shadowMesh);

  // ---- accent edge line (<=10% of frame, signal red) ----
  const accentGeo = new BoxGeometry(width * 0.9, 0.02, 0.02);
  const accentMat = new MeshStandardNodeMaterial({
    roughness: 0.5,
    metalness: 0.2,
  });
  accentMat.colorNode = color(COLORS.accent);
  accentMat.emissiveNode = color(COLORS.accent).mul(0.9);
  const accentMesh = new THREE.Mesh(accentGeo, accentMat);
  accentMesh.position.set(0, -height / 2 + 0.08, cardDepth / 2 + 0.02);
  group.add(accentMesh);

  // ---- rim/accent light, node-local, low intensity ----
  const rimLight = new PointLight(new Color(COLORS.accent), 0.5, 3.0, 2.0);
  rimLight.position.set(width * 0.6, height * 0.4, 0.8);
  group.add(rimLight);

  // ---- image plane ----
  const imgWidth = width * 0.86;
  const imgHeight = height * 0.72;
  const imgGeo = new PlaneGeometry(imgWidth, imgHeight);
  const imgMat = new MeshBasicNodeMaterial({ transparent: true });
  imgMat.opacity = 0;
  const imgMesh = new THREE.Mesh(imgGeo, imgMat);
  imgMesh.position.set(0, height * 0.06, cardDepth / 2 + 0.01);
  group.add(imgMesh);

  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      if (!imgMat) return;
      tex.colorSpace = SRGBColorSpace;
      loadedTexture = tex;
      imgMat.map = tex;
      imgMat.needsUpdate = true;
      gsap.to(imgMat, { opacity: 1, duration: 0.5, ease: 'power2.out' });
    }).catch(() => {});
  }

  // ---- entrance motion: weighted-settle ----
  group.scale.set(0.96, 0.96, 0.96);
  group.position.y += 0.12;
  const tl = gsap.timeline({ delay: 0.08 });
  tl.to(group.scale, {
    x: 1.04, y: 1.04, z: 1.04,
    duration: 0.55,
    ease: 'power3.out',
  }).to(group.scale, {
    x: 1, y: 1, z: 1,
    duration: 0.9,
    ease: 'power4.out',
  }, '-=0.1');
  tl.to(group.position, {
    y: '-=0.12',
    duration: 0.9,
    ease: 'power4.out',
  }, '<');

  // idle: single slow breathing transform (<=2%)
  const idleTl = gsap.timeline({ repeat: -1, yoyo: true, delay: 1.2 });
  idleTl.to(cardMesh.scale, {
    x: 1.015, y: 1.015, z: 1.015,
    duration: 3.2,
    ease: 'sine.inOut',
  });

  // ---- cleanup ----
  group.userData.handlers = {};
  group.userData.cleanup = () => {
    tl.kill();
    idleTl.kill();
    gsap.killTweensOf(imgMat);
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(cardMesh.scale);

    cardGeo.dispose();
    cardMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
    accentGeo.dispose();
    accentMat.dispose();
    imgGeo.dispose();
    imgMat.dispose();

    if (loadedTexture) {
      loadedTexture.dispose();
    }

    group.remove(rimLight);
    group.clear();
  };

  return group;
}
